style.css:
@-moz-document url-prefix("https://www.google.com/"), url-prefix("https://www.google.de/"), url-prefix("https://google.com"), url-prefix("https://google.de"), url-prefix("https://www.google.com.tr/"), url-prefix("https://google.com.tr") {
/* Google Pink - plain CSS for Stylish */

  /* Background */
  html,
  body,
  #main,
  #rcnt,
  #cnt,
  #searchform,
  .sfbg,
  .appbar,
  #appbar,
  .L3eUgb,
  .o3j99,
  .c93Gbe {
    background-color: #ffe4ec !important;
  }

  body {
    color: #4a1f2e !important;
  }

  /* Search box */
  .RNNXgb {
    background-color: #fff5f8 !important;
    border: 2px solid #f4a6c0 !important;
    box-shadow: none !important;
  }

  .RNNXgb:hover,
  .RNNXgb:focus-within {
    border-color: #e75480 !important;
    box-shadow: 0 2px 8px rgba(231, 84, 128, 0.25) !important;
  }

  textarea[name="q"],
  input[name="q"] {
    background: transparent !important;
    color: #4a1f2e !important;
  }

  /* Suggestion dropdown */
  .aajZCb,
  .erkvQe,
  .UUbT9 {
    background-color: #fff5f8 !important;
  }

  /* Buttons */
  input[type="submit"],
  .gNO89b,
  .RNmpXc,
  .gb_A,
  .gb_Ua,
  .gb_Ld,
  a[href*="ServiceLogin"] {
    background-color: #e75480 !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 20px !important;
  }

  input[type="submit"]:hover,
  .gNO89b:hover,
  .RNmpXc:hover,
  a[href*="ServiceLogin"]:hover {
    background-color: #c2185b !important;
    box-shadow: 0 2px 6px rgba(194, 24, 91, 0.35) !important;
  }

  /* Filter bar on results page */
  .crJ18e a,
  .IUOThf a,
  .LatpMc {
    background-color: #fff5f8 !important;
    border: 1px solid #f4a6c0 !important;
    border-radius: 18px !important;
  }

  .crJ18e [aria-current="page"],
  .LatpMc[aria-selected="true"] {
    background-color: #e75480 !important;
    color: #ffffff !important;
  }

  /* Result links */
  #search a h3,
  #rso a h3 {
    color: #b0124f !important;
  }

  #search a:visited h3,
  #rso a:visited h3 {
    color: #8e2456 !important;
  }

  /* Result cards */
  .g,
  .MjjYud,
  .ULSxyf {
    background-color: transparent !important;
  }

  /* Footer (country row and link row) */
  .fbar,
  #footcnt,
  .c93Gbe,
  .uU7dJb,
  .KxwPGc,
  .SSwjIe,
  .AghGtd,
  .iTjxkf,
  footer,
  [role="contentinfo"] {
    background-color: #f8bbd0 !important;
    border-color: #f4a6c0 !important;
  }

  .uU7dJb {
    background-color: #f48fb1 !important;
    border-bottom: 1px solid #e75480 !important;
  }

  .c93Gbe,
  .c93Gbe a,
  .c93Gbe span,
  .c93Gbe div,
  .uU7dJb,
  .pHiOh,
  footer a,
  [role="contentinfo"] a {
    color: #4a1f2e !important;
  }

  .pHiOh:hover,
  .c93Gbe a:hover {
    color: #c2185b !important;
    text-decoration: underline !important;
  }
}
